events=[]
class Descriptor:
    def __get__(self, instance, owner):
        events.append((instance is None, owner.__name__))
        raise AttributeError('missing')
class Subject(object):
    __bytes__ = Descriptor()
try:
    result=bytes(Subject())
    actual=('ok',type(result).__name__,repr(result),events)
except BaseException as error:
    actual=(type(error).__name__,str(error),events)
print(repr(actual))

